public class Main {
    public static void main(String[] args) {
        Produk p = new Produk("Kopi", 25000);
        System.out.println(p);
    }
}

class Produk {
    String nama;
    int harga;

    Produk(String nama, int harga) {
        this.nama = nama;
        this.harga = harga;
    }

    @Override
    public String toString() {
        return nama + " - Rp" + harga;
    }
}

